"""Related work, limits of SOTA claims and research options."""
def pages(w, table, links):
    w.page("Исследования и воспроизводимость","С чем сравнивать подходы к памяти",
           "В опубликованной системе результат зависит от представления памяти, прав инструментов, модели и обучающих траекторий. Единая задача и одинаковое название метрики ещё не выравнивают эксперимент.")
    table(["Работа и объект памяти","Совместимое сравнение для статьи"],[
        ["Compact-Bench и накопление путей в Pi","На E2 воспроизвести штатный индекс и уравнять токенный бюджет. На сырых трассах сравнить с настоящим Pi, который переносит известные операции над файлами."],
        ["CompactionBench и APEC","Сопоставить рекурсивные сводки на одной цепочке требований, общей рабочей копии и общем решателе. Измерить проход исполняемых требований и стоимость повторного сжатия."],
        ["CoReMem и WikiTrace","Зафиксировать модель, исходные факты и промежуточный checkout. Изменять наличие ссылки на исходное свидетельство или разрешение прочитать трассу. Считать как приобретённые, так и потерянные решения."],
        ["TVCACHE и ToolCacheAgent","В TVCACHE повторные rollout сопоставляются по полному префиксу действий. В ToolCacheAgent политика адаптируется к рабочей нагрузке. Нужен один backend с одинаковыми ценами и правилами инвалидации."],
        ["MIRIX‑2.0 и память процедур","Повторить агента и интерфейс авторов на тех же unseen-играх с одинаковым бюджетом. AWM, ReasoningBank и отсутствие памяти должны быть доступны на равных условиях."]],[5.45,11.65])
    w.p("В E3 опубликованные сводки позволяют только приблизить контроль Pi. Только пути из предыдущих сводок дали 18,21% против 19,40% у всех типов, разница +1,20 п.п. [0,44; 2,20]. На 34 границах 12 улучшений, 0 ухудшений и 22 ничьи. Больше всего добавили SHA и присваивания переменных. Сырых вызовов файловых инструментов здесь нет.")
    w.h("Публикации и материалы конференции")
    w.p("На третьей фотографии указана система MemOS 1.0. Её архитектуру описали Zhiyu Li и соавторы в работе MemOS: A Memory OS for AI System. На первых двух слайдах обсуждаются момент чтения и пересмотр записей. По фотографиям нельзя однозначно установить текстовый первоисточник обеих схем.")
    w.p("MIRIX‑2.0 даёт проверяемую постановку процедурной памяти. Демо-трек ICDE 2027 принимает описание пользовательской демонстрации объёмом до четырёх страниц вместе со ссылками. Официальный срок — 7 декабря 2026, 23:59 AoE, то есть 8 декабря в 14:59 по Москве. Принятые работы входят в proceedings. Если выбрать демо, можно показать источник записи и изменение решения при устаревании.")
    links(("CompactionBench и APEC","https://www.microsoft.com/en-us/research/publication/benchmarking-long-horizon-agent-context-compaction-with-compactionbench/"),("Pi","https://docs.pi.dev/latest/compaction#cumulative-file-tracking"),("CoReMem","https://arxiv.org/html/2611.17316v1"),("WikiTrace","https://arxiv.org/html/2611.14320v1"))
    links(("ToolCacheAgent","https://openreview.net/pdf?id=tX3YcbNa5w"),("MIRIX‑2.0","https://arxiv.org/html/2611.12068v1"),("MemOS","https://arxiv.org/abs/2507.03724"),("ICDE 2027, официальный CFP","https://icde2027.github.io/cf-demonstrations.html"))
    w.page("Выбор исследовательской программы","Три направления для следующей серии",
           "Для каждого кандидата нужен один механизм, сильная простая альтернатива и заранее заданное условие, при котором результат заслуживает продолжения.")
    w.h("1   Возвращать вытесненные реквизиты с проверкой источника")
    w.p("Проверить, помогает ли возврат путей, SHA и наблюдавшихся значений после нескольких сжатий чаще получать рабочий патч. Дать каждой политике собственную предыдущую сводку. Из общей ревизии запустить одного и того же решателя со штатным Pi, сырым хвостом, только путями и всеми типами. В отдельных условиях добавить ссылку на наблюдение и дешёвую проверку его актуальности. Главная метрика — доля решённых задач по официальным тестам. Дополнительно измерить потерянные решения, повторный поиск, входные токены и цену чтения исходного события.")
    w.h("2   Сохранять дорогие наблюдения с условиями их действия")
    w.p("При записи фиксировать фактически прочитанные файлы и параметры среды. При чтении проверять только те изменения, которые могли повлиять на наблюдение. Раздельно испытать медленный изолированный инструмент и дешёвый локальный API. Сравнить с очисткой всей памяти, одной покрывающей записью, хешем файла и реальным методом отбора тестов. Критерий продолжения — сокращение фактического времени на новых репозиториях при сопоставимом риске устаревания и доле решённых задач.")
    w.h("3   Разделить память о промахах и правила поиска")
    w.p("Проверить, когда опыт из предыдущих задач корректирует приоритет текущего действия. Сравнивать с циклическим обходом от текущей позиции без дополнительной памяти, обычной давностью, исходным рангом модели и памятью о другом предмете той же формы. На коде отдельно измерить, помог ли предложенный тест воспроизвести ошибку. Ранжирование уже сохранённых рецептов ограничивает потолок. Перенос с бытовых задач на выбор теста требует отдельного опыта.")
    w.h("Условие заявления о превосходстве")
    w.p("Заморозить правила до просмотра нового результата. Для каждой строки зафиксировать снапшот модели, средства доступа, одинаковые начальные состояния, лимиты и бюджет записи и чтения памяти. Воспроизвести сильнейший совместимый открытый метод в том же запуске, рандомизировать порядок условий, повторить стохастические прогоны и считать интервалы по независимым задачам или проектам.")
    w.p("Подробные журналы, пообъектные результаты, сырые прогнозы, версии источников и протоколы сгруппированы по каталогам compact, validity, procedure, repair и alfworld в архиве раунда. Эти записи позволяют заново вычислить показатели каждой серии.","Caption")

